#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char s[505];
    if (scanf("%s", s) != 1) return 0;

    int max_len = 1;

    for (int i = 0; i < n; i++) {
        // Palíndromo de comprimento ímpar centrado em i
        int l = i, r = i;
        while (l >= 0 && r < n && s[l] == s[r]) {
            int len = r - l + 1;
            if (len > max_len) {
                max_len = len;
            }
            l--;
            r++;
        }

        // Palíndromo de comprimento par centrado entre i e i+1
        l = i;
        r = i + 1;
        while (l >= 0 && r < n && s[l] == s[r]) {
            int len = r - l + 1;
            if (len > max_len) {
                max_len = len;
            }
            l--;
            r++;
        }
    }

    printf("%d\n", max_len);

    return 0;
}
